using System.Text.Json;
using System.Xml.Linq;
using ChartForgeX.Interactivity.Html;
using ChartForgeX.Markup.Mermaid;
using ChartForgeX.Mermaid;
using ChartForgeX.VisualArtifacts;
using Xunit;
namespace ChartForgeX.Tests;
[Collection(nameof(FontRegistryCollection))]
public sealed class SequenceNavigationTests {
    [Theory] [InlineData("https://example.invalid/guide")] [InlineData("mailto:reader@example.invalid")] [InlineData("../guide?q=1&x=2")] [InlineData("#guide")]
    public void SafeTargetsAndLiteralLabelsRemainExact(string href) {var link=new VisualNavigationLink("<Guide> & \"status\"",href);Assert.Equal(href,link.Href);Assert.Equal("<Guide> & \"status\"",link.Label);}
    [Theory] [InlineData("javascript:alert(1)")] [InlineData("data:text/html,unsafe")] [InlineData("https://example.invalid/\nunsafe")] [InlineData("")]
    public void UnsafeTargetsRejectAtTheReusableOwner(string href)=>Assert.Throws<ArgumentException>(()=>new VisualNavigationLink("Guide",href));
    [Fact] public void ListsAndPreparedPortableSnapshotsAreDetachedAndStaticPixelsAreUnchanged() {
        var model=Basic();var svg=model.ToSvg();var png=model.ToPng();var links=new[]{new VisualNavigationLink("Guide","#guide"),new VisualNavigationLink("Status","../status")};model.Participants[0].NavigationLinks=links;links[0]=new VisualNavigationLink("Changed","#changed");var list=Assert.IsAssignableFrom<IList<VisualNavigationLink>>(model.Participants[0].NavigationLinks);Assert.Throws<NotSupportedException>(()=>list[0]=links[0]);Assert.Equal("Guide",model.Participants[0].NavigationLinks[0].Label);
        var prepared=SequencePreparedCompiler.PrepareDefault(model);var artifact=prepared.ToArtifact(model.Id,VisualArtifactKind.Sequence);var envelope=artifact.ToInterchangeEnvelope();var json=artifact.ToInterchangeJson();SequenceMessageFixture.Capture("sequence-navigation-prepared",prepared);Assert.Equal(svg,prepared.ToSvg());Assert.Equal(png,prepared.ToPng());Assert.Equal(2,envelope.Version);var restored=VisualArtifactInterchangeEnvelope.FromJson(json).ToSequenceArtifact();Assert.Equal(new[]{"Guide","Status"},restored.Participants[0].NavigationLinks.Select(item=>item.Label));model.Participants[0].NavigationLinks=Array.Empty<VisualNavigationLink>();envelope.Nodes[0].Sequence!.NavigationLinks.Clear();Assert.Equal(json,artifact.ToInterchangeJson());Assert.Equal("Guide",restored.Participants[0].NavigationLinks[0].Label);Assert.Equal(svg,restored.ToSvg());Assert.Equal(png,restored.ToPng());Assert.Throws<NotSupportedException>(()=>VisualArtifactInterchangeEnvelope.FromJson(json.Replace("\"version\":2","\"version\":1",StringComparison.Ordinal)));
    }
    [Theory] [InlineData(ChartForgeX.Themes.VisualThemeMode.Light)] [InlineData(ChartForgeX.Themes.VisualThemeMode.Dark)]
    public void NavigationOnlyThemeAndExplicitContextCaptureRestoreActualNativePaintOnce(ChartForgeX.Themes.VisualThemeMode mode) {var model=Basic();model.ThemeMode=mode;model.Participants[0].NavigationLinks=new[]{new VisualNavigationLink("Guide","#guide")};var raw=VisualArtifactInterchangeEnvelope.FromJson(model.ToVisualArtifact().ToInterchangeJson()).ToSequenceArtifact();Assert.Equal(model.ToSvg(),raw.ToSvg());Assert.Equal(model.ToPng(),raw.ToPng());var context=new ChartForgeX.Rendering.VisualRenderContext(new ChartForgeX.Rendering.VisualLayoutOptions(new ChartForgeX.Rendering.VisualSize(1500,1100),20),themeMode:mode);var prepared=model.Prepare(context);var restored=VisualArtifactInterchangeEnvelope.FromJson(prepared.ToArtifact(model.Id,VisualArtifactKind.Sequence).ToInterchangeJson()).ToSequenceArtifact();var again=restored.Prepare(context);SequenceMessageFixture.Capture("sequence-navigation-theme-"+mode,prepared);Assert.Equal(prepared.ToSvg(),again.ToSvg());Assert.Equal(prepared.ToPng(),again.ToPng());Assert.Equal(mode,restored.ThemeMode);}
    [Fact] public void EmptyNavigationKeepsOrdinaryWireAndExactHtmlWithoutAController() {
        var model=Basic();var json=model.ToVisualArtifact().ToInterchangeJson();model.Participants[0].NavigationLinks=Array.Empty<VisualNavigationLink>();Assert.Equal(json,model.ToVisualArtifact().ToInterchangeJson());Assert.DoesNotContain("navigationLinks",json);Assert.Equal(model.ToVisualArtifact().ToHtmlPage(),model.ToNavigationHtmlPage());Assert.Equal(model.ToNavigationHtmlPage(),model.ToNavigationHtmlPage(new HtmlSequenceNavigationOptions{InitiallyExpanded=true}));
    }
    [Fact] public void HtmlUsesPreparedRegionsEscapedLabelsAndOrderedNativeDisclosureLinks() {
        var model=Basic();model.Participants[0].Label="<Review> & \"owner\"";model.Participants[0].NavigationLinks=new[]{new VisualNavigationLink("<Guide>","#guide"),new VisualNavigationLink("Status & details","../status?q=1&x=2")};var options=new HtmlSequenceNavigationOptions{InitiallyExpanded=true};var html=model.ToNavigationHtmlPage(options);CaptureHtml("sequence-navigation-host",html);options.InitiallyExpanded=false;Assert.Contains("<details",html);Assert.Contains(" open",html);Assert.Contains("&lt;Guide&gt;",html);Assert.Contains("Status &amp; details",html);Assert.Contains("../status?q=1&amp;x=2",html);Assert.DoesNotContain("<script",html);Assert.DoesNotContain("onclick",html);Assert.True(html.IndexOf("#guide",StringComparison.Ordinal)<html.IndexOf("../status",StringComparison.Ordinal));Assert.Contains("data-source-id=\"A\"",html);Assert.Contains(model.ToSvg(),html);Assert.DoesNotContain(" open",model.ToNavigationHtmlPage(options));
    }
    [Fact] public void SourceMapsLinksAndForceMenusOnceWithoutLosingRawOrderOrSpans() {
        var source=SequenceNavigationSourceFixture.Canonical();var result=MermaidRenderer.Render(source,new MermaidRenderOptions{WarningPolicy=MermaidWarningPolicy.Reject});Assert.Empty(result.Diagnostics);var document=Assert.IsType<MermaidSequenceDocument>(result.Document);Assert.True(document.Configuration.SequenceForceMenus);var model=Assert.IsType<SequenceArtifact>(result.Artifact!.Model);Assert.Equal(new[]{"Guide","Status"},model.Participants[0].NavigationLinks.Select(item=>item.Label));Assert.Equal(new[]{"#guide","#status"},model.Participants[0].NavigationLinks.Select(item=>item.Href));Assert.Equal("#status",model.Participants[0].Href);using var raw=JsonDocument.Parse(model.Participants[0].Metadata["mermaid.menu.entries"]);Assert.Equal(3,raw.RootElement.GetArrayLength());Assert.Equal(3,raw.RootElement.EnumerateArray().Select(e=>e.GetProperty("line").GetInt32()).Distinct().Count());
        var typed=document.ToSequenceArtifact();var fence=new MermaidVisualMarkupParser(new MermaidRenderOptions{WarningPolicy=MermaidWarningPolicy.Reject}).Parse("```mermaid\n"+source+"\n```");Assert.Empty(fence.Diagnostics);Assert.Equal(result.Artifact.ToSvg(),typed.ToSvg());Assert.Equal(result.Artifact.ToSvg(),Assert.Single(fence.Artifacts).ToSvg());var html=model.ToNavigationHtmlPage(new HtmlSequenceNavigationOptions{InitiallyExpanded=document.Configuration.SequenceForceMenus==true});CaptureHtml("sequence-navigation-source",html);Assert.Contains(" open",html);
    }
    [Fact] public void RepeatedLabelReplacementRetainsFirstOrderAndUnsafeLatestDoesNotReviveAnOldTarget() {
        var source="sequenceDiagram\nparticipant A\nparticipant B\nlink A: Guide @ #old\nlinks A: {\"Status\":\"#status\",\"Guide\":\"#new\"}\nlink A: Guide @ javascript:alert(1)\nA->>B: Save";var result=MermaidRenderer.Render(source);Assert.False(result.HasErrors);Assert.Contains(result.Diagnostics,d=>d.Span.Line==6);var model=Assert.IsType<SequenceArtifact>(result.Artifact!.Model);Assert.Equal("Status",Assert.Single(model.Participants[0].NavigationLinks).Label);Assert.Null(model.Participants[0].Href);using var raw=JsonDocument.Parse(model.Participants[0].Metadata["mermaid.menu.entries"]);Assert.Equal(3,raw.RootElement.GetArrayLength());SequenceMessageFixture.Capture("sequence-navigation-unsafe-replacement",model);
    }
    [Theory] [InlineData("'true'")] [InlineData("1")] [InlineData("null")]
    public void InvalidForceMenusIsLocatedBeforeArtifact(string value){var result=MermaidRenderer.Render("%%{init:{\"sequence\":{\"forceMenus\":"+value+"}}}%%\nsequenceDiagram\nA->>B: Save");SequenceSourcePolicyFixture.CaptureDiagnostics("sequence-navigation-invalid-"+value.Replace("'",""),result);Assert.True(result.HasErrors);Assert.Null(result.Artifact);Assert.Contains(result.Diagnostics,d=>d.Span.Line==1&&d.Message.Contains("forceMenus",StringComparison.Ordinal));}
    [Fact] public void HiddenUnusedParticipantDoesNotCreateAnUnanchoredMenu() {var model=Basic();model.AddParticipant("Unused","Unused");model.Participants[2].NavigationLinks=new[]{new VisualNavigationLink("Guide","#guide")};model.Layout=new SequenceLayoutPolicy(hideUnusedParticipants:true);var html=model.ToNavigationHtmlPage();Assert.DoesNotContain("<details",html);Assert.Contains("Unused",model.ToVisualArtifact().ToInterchangeJson());}
    [Theory] [InlineData("compact",ChartForgeX.Themes.VisualThemeMode.Light)] [InlineData("compact",ChartForgeX.Themes.VisualThemeMode.Dark)] [InlineData("wide",ChartForgeX.Themes.VisualThemeMode.Light)] [InlineData("wide",ChartForgeX.Themes.VisualThemeMode.Dark)]
    public void CompleteProgramsRespectCoreAndSourceAwareHostBoundaries(string variant,ChartForgeX.Themes.VisualThemeMode mode) {var model=SequenceNavigationRecipe.Create(variant,mode);SequenceMessageFixture.Capture("sequence-navigation-recipe-"+variant+"-"+mode,model);var native=ExampleRecipeSource.Emit(ExampleRecipes.Named("sequence-navigation"),variant,"Participant navigation","Detached links",mode,variant=="compact"?390:1000,820,false,"Sequence");var source=ExampleRecipeSource.EmitSequenceNavigation(variant,mode);Assert.DoesNotContain("ChartForgeX.Mermaid",native);Assert.DoesNotContain("ChartForgeX.Interactivity",native);Assert.Contains("VisualNavigationLink",native);Assert.Contains("SequenceForceMenus",source);Assert.Contains("ToNavigationHtmlPage",source);Assert.DoesNotContain("{{",source);}
    internal static SequenceArtifact Basic()=>SequenceArtifact.Create("navigation").WithSize(1000,820).AddParticipant("A","Review").AddParticipant("B","Archive").AddMessage("A","B","Save");
    internal static void CaptureHtml(string stem,string html){var output=Environment.GetEnvironmentVariable("CFX_NATIVE_CAPTURE_DIRECTORY");if(string.IsNullOrWhiteSpace(output))return;Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,stem+".html"),html);}
}
internal static class SequenceNavigationSourceFixture {internal static string Canonical()=>File.ReadAllText(Path.Combine(TestRepository.Root,"Build","PackageConsumers","Adapters","sequence-navigation.mmd"));}
